import { PLATFORMS } from './completeness.mjs'
import { swiftScene } from './swift-scene.mjs'
import { iosCatalog, iosScene } from './ios-scene.mjs'
import { androidOutputs, androidSupports } from './android.mjs'
import { TRIM_CHARACTERS } from './schema/value.mjs'
import { glyphOutputs } from './glyph-outputs.mjs'
import { tokenOutputs } from './tokens.mjs'

const q = JSON.stringify
const cap = value => value[0].toUpperCase() + value.slice(1)
const header =
  '// Generated by tools/codegen. Edit the React example scene declarations.\n'

/** Components the Flutter scene interpreter (`playground/scene.dart`) draws. */
const FLUTTER_COMPONENTS = new Set(
  'RadioGroup RadioOption PillTabs PillTab ToggleGroup ToggleItem OptionCard Slider NumberField SearchField OtpField Show Tag Link Meter Skeleton SkeletonText Grid Table TableHead TableRow TableCell Badge Box Value SegmentedControl SegmentedItem Switch Checkbox PreferenceRow PreferenceSection Page Section Stack Specimen Inline Icon StepList Step Progress Divider EmptyState Callout Card SectionLabel Spinner KeyCap Row Col Button IconButton Toggle FormField TextField Text Dialog DialogHeader DialogBody DialogFooter ActionBar'.split(
    ' '
  )
)
function flutterSupports(scene) {
  const visit = node =>
    typeof node === 'string' ||
    (FLUTTER_COMPONENTS.has(node.component) &&
      (node.children ?? []).every(visit) &&
      Object.values(node.slots ?? {}).every(visit))
  return visit(scene.content)
}

function staticControls(node) {
  if (typeof node === 'string') return false
  if (
    !['Button', 'Badge', 'Row', 'Col'].includes(node.component) ||
    node.bind ||
    node.derive ||
    node.slots ||
    node.on
  )
    return false
  if (
    !Object.keys(node.props ?? {}).every(key =>
      ['variant', 'size', 'tint', 'disabled'].includes(key)
    )
  )
    return false
  return ['Button', 'Badge'].includes(node.component)
    ? (node.children ?? []).every(child => typeof child === 'string')
    : (node.children ?? []).every(staticControls)
}
function staticNode(node, platform, key = 'specimen') {
  if (typeof node === 'string')
    throw new Error('Text must belong to a Button or Badge')
  const props = node.props ?? {}
  if (node.component === 'Badge') {
    const label = q((node.children ?? []).join(''))
    const size = cap(props.size ?? 'medium'),
      variant = cap(props.variant ?? 'tinted'),
      tint = cap(props.tint ?? 'primary')
    if (platform === 'winui3')
      return `new UI.Badge { Content = ${label}, Theme = theme, Size = UI.ControlSize.${size}, Variant = UI.BadgeVariant.${variant}, Tint = UI.WidgetTint.${tint} }`
    throw Error(`Static Badge emitter is not used for ${platform}`)
  }
  if (node.component === 'Button') {
    if (node.children?.some(child => typeof child !== 'string'))
      throw new Error('Button label must be text')
    const text = q((node.children ?? []).join(''))
    const size = props.size ?? 'small',
      variant = props.variant ?? 'recessed',
      tint = props.tint ?? 'primary'
    if (platform === 'swiftui')
      return `DazzUI.Button(${text}, size: .${size}, variant: .${variant}, tint: .${tint}, enabled: ${!props.disabled}) {}`
    return `new UI.Button { Content = ${text}, Theme = theme, Size = UI.ControlSize.${cap(size)}, Variant = UI.ControlVariant.${cap(variant)}, Tint = UI.WidgetTint.${cap(tint)}, IsEnabled = ${!props.disabled}, HorizontalAlignment = Microsoft.UI.Xaml.HorizontalAlignment.Left }`
  }
  const children = node.children.map((child, i) =>
    staticNode(child, platform, `${key}-${i}`)
  )
  if (platform === 'swiftui')
    return `${node.component} {\n${children.join('\n')}\n}`
  return `Stage.${node.component === 'Row' ? 'Row' : 'Column'}(theme, ${children.join(', ')})`
}

export function nativeOutputs(stories, scenes) {
  const outputs = new Map()
  outputs.set(
    'packages/dart/dazzui/example/lib/generated/expression.dart',
    `${header}const sceneTrimCodeUnits = <int>[${[...TRIM_CHARACTERS].map(c => c.charCodeAt(0)).join(',')}];\n`
  )
  const staticStories = stories.filter(
    s =>
      scenes.has(s.id) &&
      staticControls(scenes.get(s.id).content) &&
      !Object.keys(scenes.get(s.id).state ?? {}).length &&
      !(scenes.get(s.id).timers ?? []).length
  )
  // Each compiler reports what it can express; a scene it cannot is left out
  // of that platform's output and stays visible in the coverage worklist.
  const compiles = compile => {
    try {
      compile()
      return true
    } catch {
      return false
    }
  }
  const portable = stories.filter(
    s => scenes.has(s.id) && compiles(() => swiftScene(scenes.get(s.id), 0))
  )
  const iosScenes = new Map(
    [...scenes].filter(([, scene]) => compiles(() => iosScene(scene, 0)))
  )
  const flutterScenes = new Map(
    [...scenes].filter(([, scene]) => flutterSupports(scene))
  )
  outputs.set(
    'packages/swift/DazzMobileUI/Example/GeneratedStories.swift',
    iosCatalog(stories, iosScenes)
  )
  outputs.set(
    'packages/swift/DazzMobileUI/Example/Tests/scenes.json',
    JSON.stringify(Object.fromEntries(iosScenes), null, 2) + '\n'
  )
  for (const [file, content] of glyphOutputs()) outputs.set(file, content)
  for (const [file, content] of tokenOutputs()) outputs.set(file, content)
  for (const [file, content] of androidOutputs(stories, scenes))
    outputs.set(file, content)
  const normalized = stories.map(s => ({
    ...s,
    nativeKey: `${s.title}/${s.name}`.toLowerCase(),
  }))
  const flutterData = Object.fromEntries(
    normalized
      .filter(s => flutterScenes.has(s.id))
      .map(s => [
        s.nativeKey,
        {
          ...scenes.get(s.id),
          id: s.id,
          title: s.title,
          name: s.name,
          layout:
            scenes.get(s.id).content.component === 'Page' ? 'page' : s.layout,
        },
      ])
  )
  const dartLiteral = value => {
    if (typeof value === 'string') return q(value).replace(/\$/g, '\\$')
    if (Array.isArray(value)) return `[${value.map(dartLiteral).join(', ')}]`
    if (value !== null && typeof value === 'object')
      return `{${Object.entries(value)
        .map(([k, v]) => `${dartLiteral(k)}: ${dartLiteral(v)}`)
        .join(', ')}}`
    return String(value)
  }
  outputs.set(
    'packages/dart/dazzui/example/lib/generated/scenes.dart',
    `${header}import 'package:dazzui/dazzui.dart';
import '../playground/scene.dart';
import '../storybook/story.dart';

const generatedScenes = <String, Map<String, dynamic>>${dartLiteral(flutterData)};

List<StoryGroup> generatedGroups(List<StoryGroup> groups) {
  final result = [
    for (final group in groups) StoryGroup(group.name, [
      for (final page in group.pages) StoryPage(page.name, [...page.stories]),
    ]),
  ];
  for (final scene in generatedScenes.values) {
    final parts = (scene['title'] as String).split('/');
    final groupName = parts.first;
    final pageName = parts.skip(1).join('/');
    var groupIndex = result.indexWhere((group) => group.name == groupName);
    if (groupIndex < 0) {
      groupIndex = result.length;
      result.add(StoryGroup(groupName, []));
    }
    final pages = result[groupIndex].pages;
    var pageIndex = pages.indexWhere((page) => page.name == pageName);
    if (pageIndex < 0) {
      pageIndex = pages.length;
      pages.add(StoryPage(pageName, []));
    }
    final stories = pages[pageIndex].stories;
    final index = stories.indexWhere((story) =>
      (story.sourceId ?? storyId(groupName, pageName, story.name)) == scene['id'] ||
      story.name.toLowerCase() == (scene['name'] as String).toLowerCase());
    final generated = Story(scene['name'],
      (context) => GeneratedScene(key: ValueKey(scene['id']), scene: scene),
      sourceId: scene['id'],
      layout: switch (scene['layout']) {
        'fullscreen' => StoryLayout.fullscreen,
        'page' => StoryLayout.page,
        _ => StoryLayout.centered,
      });
    if (index < 0) { stories.add(generated); }
    else { stories[index] = generated; }
  }
  const pageOrder = <String>${dartLiteral([...new Set(stories.map(s => s.title))])};
  const storyOrder = <String>${dartLiteral(stories.map(s => s.id))};
  int rank(List<String> order, String key) { final i = order.indexOf(key); return i < 0 ? order.length : i; }
  for (final group in result) {
    group.pages.sort((a, b) => rank(pageOrder, '\${group.name}/\${a.name}').compareTo(rank(pageOrder, '\${group.name}/\${b.name}')));
    for (final page in group.pages) {
      page.stories.sort((a, b) => rank(storyOrder, a.sourceId ?? storyId(group.name, page.name, a.name)).compareTo(rank(storyOrder, b.sourceId ?? storyId(group.name, page.name, b.name))));
    }
  }
  return result;
}
`
  )
  outputs.set(
    'packages/swift/DazzUI/Example/Sources/Playground/Storybook/GeneratedStories.swift',
    `${header}import SwiftUI
import DazzUI

enum GeneratedStories {
  static func content(_ key: String) -> AnyView? {
    switch key.lowercased() {
${portable.map((s, i) => `case ${q(`${s.title}/${s.name}`.toLowerCase())}: return AnyView(PortableScene${i}())`).join('\n')}
    default: return nil
    }
  }
  static let entries: [(group: String, page: String, name: String, id: String, layout: StoryLayout)] = [
${portable.map(s => `(${q(s.title.split('/')[0])}, ${q(s.title.split('/')[1])}, ${q(s.name)}, ${q(s.id)}, .${scenes.get(s.id).content.component === 'Page' ? 'page' : s.layout === 'fullscreen' ? 'fullscreen' : s.layout === 'padded' ? 'page' : 'centered'}),`).join('\n')}
  ]
  static func apply(_ groups: [StoryGroup]) -> [StoryGroup] {
    var result = groups
    for entry in entries {
      let key = "\\(entry.group)/\\(entry.page)/\\(entry.name)"
      let generated = Story(entry.name, layout: entry.layout, sourceId: entry.id) { content(key)! }
      if !result.contains(where: { $0.name == entry.group }) {
        result.append(StoryGroup(entry.group, pages: []))
      }
      let g = result.firstIndex { $0.name == entry.group }!
      var pages = result[g].pages
      if !pages.contains(where: { $0.name == entry.page }) {
        pages.append(StoryPage(entry.page, stories: []))
      }
      let p = pages.firstIndex { $0.name == entry.page }!
      var stories = pages[p].stories
      if let i = stories.firstIndex(where: {
        ($0.sourceId ?? storyId(group: entry.group, page: entry.page, story: $0.name)) == entry.id ||
        $0.name.lowercased() == entry.name.lowercased()
      }) { stories[i] = generated } else { stories.append(generated) }
      pages[p] = StoryPage(entry.page, stories: stories)
      result[g] = StoryGroup(entry.group, pages: pages)
    }
    let pageOrder = ${q([...new Set(stories.map(s => s.title))])}
    return result.map { group in
      StoryGroup(group.name, pages: group.pages.sorted {
        (pageOrder.firstIndex(of: "\\(group.name)/\\($0.name)") ?? pageOrder.count) <
        (pageOrder.firstIndex(of: "\\(group.name)/\\($1.name)") ?? pageOrder.count)
      })
    }
  }
}
/// A number as the shared declaration prints it: no trailing \`.0\`.
private func sceneText(_ value: Double) -> String {
  value == value.rounded() && abs(value) < 1e15 ? String(Int(value)) : String(value)
}
${portable.map((s, i) => swiftScene(scenes.get(s.id), i)).join('\n')}
`
  )
  outputs.set(
    'packages/csharp/DazzUI/example/Storybook/GeneratedStories.cs',
    `${header}using Microsoft.UI.Xaml;
using UI = DazzUI;
namespace DazzUI.Playground.Storybook;
public static class GeneratedStories {
  public static IReadOnlyList<StoryPage> Apply(IReadOnlyList<StoryPage> pages) {
    var result = pages.ToList();
    foreach (var entry in Entries) {
      var index = result.FindIndex(page => page.Group == entry.Group && page.Name == entry.Page);
      if (index < 0) { index = result.Count; result.Add(new(entry.Group, entry.Page, [])); }
      var page = result[index];
      var stories = page.Stories.ToList();
      var storyIndex = stories.FindIndex(story => story.SourceId == entry.Id || string.Equals(story.Name, entry.Name, StringComparison.OrdinalIgnoreCase));
      var generated = new Story(entry.Name, theme => Build(entry.Group, entry.Page, entry.Name, theme)!, entry.Layout, entry.Id);
      if (storyIndex < 0) stories.Add(generated); else stories[storyIndex] = generated;
      result[index] = page with { Stories = stories };
    }
    return result;
  }
  private static readonly (string Group, string Page, string Name, string Id, StoryLayout Layout)[] Entries = [
${staticStories.map(s => `(${q(s.title.split('/')[0])}, ${q(s.title.split('/')[1])}, ${q(s.name)}, ${q(s.id)}, StoryLayout.${s.layout === 'fullscreen' ? 'Fullscreen' : s.layout === 'padded' ? 'Page' : 'Centered'}),`).join('\n')}
  ];
  public static UIElement? Build(string group, string page, string story, UI.Theme theme) => $"{group}/{page}/{story}".ToLowerInvariant() switch {
${staticStories.map(s => `${q(`${s.title}/${s.name}`.toLowerCase())} => ${staticNode(scenes.get(s.id).content, 'winui3', s.id)},`).join('\n')}
    _ => null,
  };
}
`
  )
  for (const page of [
    'Button',
    'Badge',
    'StepList',
    'Callout',
    'Card',
    'Divider',
  ])
    outputs.set(
      `packages/csharp/DazzUI/example/Stories/${page}Stories.cs`,
      `${header}using DazzUI.Playground.Storybook;
namespace DazzUI.Playground.Stories;
public static class ${page}Stories {
  public static StoryPage Page { get; } = new("Components", "${page}", [
${stories
  .filter(s => s.title === `Components/${page}`)
  .map(
    s =>
      `new(${q(s.name)}, theme => GeneratedStories.Build("Components", "${page}", ${q(s.name)}, theme) ?? ComponentExamples.${page}(theme, ${q(s.name)}), StoryLayout.${s.exportName === 'Overview' ? 'Page' : s.layout === 'fullscreen' ? 'Fullscreen' : 'Centered'}, ${q(s.id)}),`
  )
  .join('\n')}
  ]);
}
`
    )
  const report = {
    version: 1,
    total: stories.length,
    portable: scenes.size,
    reactExtensions: stories.filter(s => !scenes.has(s.id)).map(s => s.id),
    platforms: Object.fromEntries(
      PLATFORMS.map(platform => {
        const generated =
          platform === 'flutter'
            ? [...flutterScenes.keys()]
            : platform === 'swiftui'
              ? portable.map(s => s.id)
              : platform === 'ios'
                ? [...iosScenes.keys()]
                : platform === 'android'
                  ? stories
                      .filter(
                        s =>
                          scenes.has(s.id) && androidSupports(scenes.get(s.id))
                      )
                      .map(s => s.id)
                  : staticStories.map(s => s.id)
        return [
          platform,
          {
            generated,
            remaining: stories
              .filter(s => !generated.includes(s.id))
              .map(s => s.id),
            reason:
              platform === 'ios'
                ? 'Shared content, state and events mapped to native SwiftUI controls; system geometry and appearance.'
                : ['android'].includes(platform)
                  ? 'Shared content, state and events mapped to native Compose Material controls; system geometry and appearance.'
                  : 'Existing native examples remain in use until scene and adapter coverage is complete.',
          },
        ]
      })
    ),
  }
  outputs.set(
    'tools/codegen/coverage.json',
    JSON.stringify(report, null, 2) + '\n'
  )
  return outputs
}
